package org.opensourcepingpong.competition.algorithm;
import java.util.*;
public final class SingleEliminationBracketGenerator { private SingleEliminationBracketGenerator(){} public static int bracketSize(int n){if(n<2||n>64)throw new IllegalArgumentException();int s=2;while(s<n)s*=2;return s;} public static List<Integer> seedPositions(int size){if(size<2||(size&(size-1))!=0)throw new IllegalArgumentException();List<Integer> seeds=new ArrayList<>(List.of(1,2));while(seeds.size()<size){int next=seeds.size()*2;List<Integer> expanded=new ArrayList<>();for(int seed:seeds){expanded.add(seed);expanded.add(next+1-seed);}seeds=expanded;}return seeds;} public static <T> List<T> arrange(List<T> participants,long seed){if(participants==null||new HashSet<>(participants).size()!=participants.size())throw new IllegalArgumentException("participants must be unique");int size=bracketSize(participants.size());List<T> shuffled=new ArrayList<>(participants);shuffled.sort(Comparator.comparing(Object::toString));Collections.shuffle(shuffled,new Random(seed));List<T> values=new ArrayList<>(Collections.nCopies(size,null));List<Integer> positions=seedPositions(size);for(int i=0;i<shuffled.size();i++)values.set(positions.indexOf(i+1),shuffled.get(i));return values;} public static <T> void validate(List<T> slots,int participantCount){int size=bracketSize(participantCount);if(slots==null||slots.size()!=size)throw new IllegalArgumentException("bracket size must be "+size);long byes=slots.stream().filter(Objects::isNull).count();if(byes!=size-participantCount)throw new IllegalArgumentException("bye count must be "+(size-participantCount)+" but was "+byes);Set<T> unique=new HashSet<>();for(T slot:slots)if(slot!=null&&!unique.add(slot))throw new IllegalArgumentException("participant appears in more than one slot");for(int match=0;match<size/2;match++)if(slots.get(match*2)==null&&slots.get(match*2+1)==null)throw new IllegalArgumentException("first round match "+match+" contains two byes");} }
